The transition kernel of the MH takes the form:
\begin{align*}
P(\theta, d\vartheta) = q(\vartheta|\theta)\min\left\{1,r(\theta,\vartheta)\right\}d\vartheta + \left(1-\int_\Theta q(\vartheta|\theta)\min\left\{1,r(\theta,\vartheta)\right\}d\vartheta\right)\delta_\theta(d\vartheta),
\end{align*}
where $\vartheta \mapsto q(\vartheta|\theta)$ is the proposal density and where the acceptance ratio, $r(\theta,\vartheta)={p_T(y|\vartheta)p(\vartheta)q(\theta|\vartheta)}/\{p_T(y|\theta)p(\theta)q(\vartheta|\theta)\} $, depends crucially on the likelihood evaluation.

To understand the theoretical foundation of the PM, consider the extended target distribution:
\begin{align}
\bar{\pi}_N(\theta,u) = \pi(\theta)m_{N,\theta}(u)\frac{\widehat{p}_{N,T}(y|\theta,u)}{p_T(y|\theta)}. \end{align}

The acceptance probability for a candidate $(\vartheta, v)$ is thus given by
\begin{align}
    \alpha_N\left(\theta,u ;  \vartheta,v\right) 
    &=\min \left\{1, \frac{\widehat{p}_{N,T}(y \lvert \vartheta, v) p(\vartheta) q(\theta \lvert \vartheta)}{\widehat{p}_{N,T}(y \lvert \theta, u) p(\theta) q(\vartheta \lvert\theta)}\right\}. \end{align}

The transition kernel of the PM algorithm is given by
\begin{align}
    P_N(\theta, u; d\vartheta, dv) &= q(\vartheta \lvert \theta) m_{N,\vartheta}(v) \alpha_N(\theta, u; \vartheta, v) d\vartheta dv + \varrho_{N}(\theta, u) \delta_{(\theta, u)}(d\vartheta, dv), \end{align}
where 
\begin{equation}
    \varrho_{N}(\theta, u) =  1 - \int
        _{\Theta \times \mathcal{U}} q(\vartheta \lvert \theta)m_{N,\vartheta}(v) \alpha_N(\theta, u; \vartheta, v) d\vartheta dv, \end{equation}
and $\delta_{(\theta, u)}$ is the Dirac measure at $(\theta, u)$.

For any $(\theta, w) \in \Theta \times \mathcal{W}$ (with $\mathcal{W}:=(0, \infty))$, this kernel can be expressed as
\begin{align}
{P_N}(\theta, w ; \mathrm{d} \vartheta,\mathrm{d} z)= & q(\vartheta|\theta) \min \left\{1, r(\theta, \vartheta) \frac{z}{w}\right\} \mathcal{Q}_{N,\vartheta}(\mathrm{d} z) \mathrm{d}\vartheta + {\rho_N}(\theta, w)\delta_{\theta, w}(\mathrm{d} \vartheta ,\mathrm{d} z) , \end{align}
where the rejection probability is
\begin{align}
     \varrho_{N}(\theta, w) = 1- \int
    _{\Theta \times \mathcal{W}} q(\vartheta|\theta) \min\left\{1,  r(\theta, \vartheta) \frac{z}{w}\right\}
    \mathcal{Q}_{N,\vartheta}(\mathrm{d}z) \mathrm{d}\vartheta. \end{align}

Under mild conditions (see \cite{haggstrom_variance_2007}) and for $f \in L^2(\pi)$, the asymptotic variance of an MCMC estimator is finite and given by
\begin{align}
    \overline{\mathbb{V}\text{ar}}(f, Q) &= \lim_{L \rightarrow \infty} \frac{1}{L} \mathbb{E} \left[\left(\sum_{\ell=0}^{L-1} f(\theta_\ell) - \pi(f)\right)^2 \right] 
    = \mathbb{V}\text{ar}(f(\theta_0)) \operatorname{IF}(f, Q), \end{align}
where the inefficiency factor 
\begin{equation}
    \operatorname{IF}(f, Q) = 1 + 2\sum_{\ell=1}^{\infty}\frac{\mathbb{C}\text{ov}(f(\theta_0),f(\theta_\ell))}{\mathbb{V}\text{ar}(f(\theta_0))} < \infty \end{equation}
is a measure of how much the estimator is penalized by the correlation induced by the Markov chain.

This quantity is defined, for functions $\bar f \in L^2(\bar{\pi}_N)$, as:
\begin{equation}
    \text{CT}(\bar f,P_\sigma) :=  \frac{\operatorname{IF}(\bar f,P_\sigma)}{\sigma^2} \propto \frac{\overline{\mathbb{V}\text{ar}}(\bar f,P_\sigma)}{\sigma^2}, \end{equation}
where the transition kernel $P_\sigma$ of the PM chain becomes, under Assumption \eqref{hypi},
\begin{align}
   {P_\sigma}\left(\theta,\omega ; \mathrm{d} \vartheta,\mathrm{d}\zeta\right)&= q(\vartheta|\theta) \varphi(\zeta ; -\sigma^2/2, \sigma^2) \min \left\{1, r(\theta, \vartheta) \exp\{\zeta-\omega\}\right\}  \mathrm{d}\vartheta \mathrm{d}\zeta \nonumber\\*
   &\quad +  {\rho_\sigma}(\theta,\omega) \delta_{\theta, \omega}(\mathrm{d} \vartheta ,\mathrm{d}\zeta), \end{align}
with \({\rho_\sigma}(\theta,\omega)\) representing the rejection probability and $\varphi(x; \mu, \sigma^2)$ the density of a $\mathcal{N}(\mu,\sigma^2)$ evaluated at $x$.

Following these observations, \cite{schmon_large-sample_2021} proposed a method of implementation the PM algorithm with the optimal number of particles, $N_{\text{opt}}$. After using Table 1 in \cite{schmon_large-sample_2021} to identify the estimated optimal scaling parameter $l_\text{opt}$ and additive noise standard deviation $\sigma_\text{opt}$ as a function of the parameter dimension $d$, this method can be summarized as follows:
\begin{enumerate}
    \item Run a preliminary PM algorithm with some initial $N_1$ to obtain $\hat \theta_{N_1}$ and $\widehat \Sigma_{N_1}$, the posterior mean and covariance estimates of $\theta$. At this stage, the proposal density is a Normal random walk with covariance ${l_{\text{opt}}^2 \Sigma_p}/{d}$, where $\Sigma_p$ is some positive-definite matrix. \item Let $\sigma_N^2(\hat \theta_{N_1})$ denote the variance of the additive noise $\omega_N(\hat \theta_{N_1})$, defined as:
    \begin{align}
        \sigma_N^2(\hat \theta_{N_1}) &= \mathbb{V}\text{ar}(\omega_N(\hat \theta_{N_1})|\hat \theta_{N_1})\nonumber \\
        &= \mathbb{V}\text{ar}\big(\log\{\widehat p_N(y |\hat \theta_{N_1}, \widehat U)\}- \log\{p_N(y |\hat \theta_{N_1})\}\big|\hat \theta_{N_1}\big) \nonumber\\
        &= \mathbb{V}\text{ar}\big(\log\{\widehat p_N(y |\hat \theta_{N_1}, \widehat U)\}|\hat \theta_{N_1}\big), \end{align}
    where the auxiliary variables $\widehat U|\hat\theta_{N_1} \sim m_{N, \hat \theta_{N_1}}$. 
    We estimate $\sigma_N^2(\hat \theta_{N_1})$ via Monte Carlo methods for multiple values of $N$ and select $N_{\text{opt}}$ such that the variance estimate of the additive noise, $\hat \sigma_{N_{\text{opt}}}^2(\hat \theta_{N_1})$, matches the target value $\sigma_{\text{opt}}^2$. 
    This step is facilitated by the inverse proportionality between $1/\sigma^2$ and $N$, as stated in Assumption~\eqref{hypii}. Thanks to this relationship, one can choose a reasonable interval for $N$ and efficiently narrow down the search, as the approximate location of the optimal $N$ can be anticipated. \item Execute the PM algorithm using $N_{\text{opt}}$ and a Normal random walk proposal density with covariance ${l_{\text{opt}}^2\widehat \Sigma_{N_1}}/{d}$.

The transition dynamics satisfy
\begin{align}
    \mathbb{P}\left[(\theta_{\ell+1}, W_{\ell+1}) \in A |\mathcal{G}_\ell\right] = P_{N_\ell}(\theta_\ell, W_\ell; A) = P_{\psi(N_{\ell-1}, \hat\sigma_\ell)}(\theta_\ell, W_\ell; A), \end{align}
where $P_{N_\ell}$ is the PM transition kernel defined in equation~(\ref{equa5}), and $\psi$ is the adaptation function given by
\begin{align*}
\psi(N_{\ell-1}, \hat{\sigma}_\ell) = N_{\ell-1} + a \cdot \kappa_\ell (\hat\sigma_\ell) \cdot \mathds{1}(\ell \in K\mathbb{N}^*),
\end{align*}
with step size \( a \in \mathbb{N}^* \) and $K\mathbb{N}^*=\{Kj , j \in \mathbb{N}^*\}$.

The random variable $\kappa_\ell$ indicates the direction of adaptation at iteration $\ell$ and is defined conditionally on $\mathcal{G}_{\ell-1}$ as:
\begin{align*}
\kappa_\ell(\hat\sigma_\ell) = 
\begin{cases}
-1 & \text{with probability } p_{\lfloor \frac{\ell}{K} \rfloor}, \quad \text{if } \hat{\sigma}_\ell < {\sigma}_{\text{opt}} - \sigma_{\text{e}} \\
0 & \text{with probability } 1, \quad \text{if } |\hat{\sigma}_\ell - {\sigma}_{\text{opt}}| \leqslant \sigma_{\text{e}} \\
+1 & \text{with probability } p_{\lfloor \frac{\ell}{K} \rfloor}, \quad \text{if } \hat{\sigma}_\ell > {\sigma}_{\text{opt}} + \sigma_{\text{e}}
\end{cases},
\end{align*}
where $\hat{\sigma}_\ell$ is the estimate of the standard deviation of the additive noise at iteration $\ell$ obtained from  \textit{epoch} $j$, $p_j$ is an adaptation probability, and $\sigma_{\text{e}}$ is a tolerance parameter.

First, the theoretical variance limit establishes that as $T \to \infty$, the additive noise variance converges to 
\begin{align}
    \sigma^2 :=  \lim_{T \to \infty} \mathbb{V}\text{ar}\left( \omega_N(\bar\theta)\right) = \lim_{T \to \infty} \mathbb{V}\text{ar}\left(\log \widehat{p}_{N,T}(y|\bar{\theta}, \bar{V})\right), \quad \bar{V}|\bar\theta \sim m_{N,\bar{\theta}}, \end{align}
with $\bar{\theta}$ being the limiting parameter in \cite[Assumption~1 and Assumption~3]{schmon_large-sample_2021}, with Assumption~1 being a Bernstein–von Mises-type posterior concentration around $\bar{\theta}$ and Assumption~3 a central limit theorem for the additive noise holding uniformly in a neighborhood of $\bar{\theta}$.

Since $\bar{\theta}$ is unknown in practice, we approximate it, after each \textit{epoch}, using the sample mean of all accepted parameters up to iteration $\ell$, that is
\begin{equation}
    \hat{\theta}_\ell =
    \begin{cases}
    \hat{\theta}_{\ell-1} & \text{if } \ell \notin K\mathbb{N}^*\\
    \frac{1}{\ell}\sum_{i=1}^\ell \theta_i & \text{if } \ell \in K\mathbb{N}^*
    \end{cases}. \end{equation}

At iteration $\ell=jK$, the empirical variance $\hat{\sigma}_\ell^2$ is then calculated as the sample variance of these transformed log-likelihood estimates within the $j$-th \textit{epoch} 
{\small
 \begin{equation}
    \hat{\sigma}_\ell^2 = \frac{1}{K-1} \sum_{i = \ell-K+1}^{\ell} \left( \log \left\{\widehat{p}_{N_{i-1},T}(y | \hat{\theta}_{i-1}, \widehat{V}_i)\right\} - \frac{1}{K} \sum_{i = \ell-K+1}^{\ell} \log \left\{\widehat{p}_{N_{i-1},T}(y |\hat{\theta}_{i-1}, \widehat{V}_i)\right\} \right)^2. \end{equation}
}

\For{each iteration $\ell = 1$ to $L$}
    \State Propose $\vartheta_\ell|\theta_{\ell-1} \sim \mathcal{N}(\theta_{\ell-1}, {l_{\text{opt}}^2 \Sigma_p}/{d})$, with $\Sigma_p$ as defined in Step~\ref{step1} of Section~\ref{sec:review}
    \State Generate likelihood estimate $\widehat{p}_{N_{\ell-1},T}(y|\vartheta_\ell,v_\ell)$
    \State Compute $\widehat{p}_{N_{\ell-1},T}(y|\hat{\theta}_{\ell-1},\hat{v}_\ell)$, where $$\hat v_\ell = h(v_\ell, \vartheta_\ell, \hat\theta_{\ell-1}) \text{ and }
    \hat v_\ell| \hat\theta_{\ell-1}\sim m_{N_{\ell-1},\hat\theta_{\ell-1}}
   \text{ when } v_\ell|\vartheta_\ell \sim m_{N_{\ell-1},\vartheta_\ell}$$
    \State Accept/reject $\vartheta_\ell$ with  probability $\alpha_{N_{\ell-1}}$ defined in Equation \eqref{alphaN}
    \State Let $N_{\ell}=N_{\ell-1}$ and $\hat\theta_{\ell}=\hat\theta_{\ell-1}$
    \If{$\ell \in K\mathbb{N}^*$}
        \State Estimate current standard deviation of the additive noise $\widehat{\sigma}_\ell$ using \eqref{hatsigma}
        \If{$\widehat{\sigma}_\ell > \sigma_{\text{opt}} + \sigma_\text{e}$} \State $N_\ell=N_{\ell}+a$ with probability $p_j$ ($\ell=Kj$)
        \ElsIf{$\widehat{\sigma}_\ell < \sigma_{\text{opt}} - \sigma_\text{e}$ and $N_{\ell-1} > a$}
            \State $N_\ell=N_{\ell}-a$  with probability $p_j$
        \EndIf
        \State Update sample mean $\hat{\theta}_\ell$ of parameters using Equation \eqref{samplemean}
    \EndIf

Compute $\widehat{p}_{N_{\ell-1},T}(y|\hat{\theta}_{\ell-1},\hat{v}_\ell)$, where $$\hat v_\ell = h(v_\ell, \vartheta_\ell, \hat\theta_{\ell-1}) \text{ and }
    \hat v_\ell| \hat\theta_{\ell-1}\sim m_{N_{\ell-1},\hat\theta_{\ell-1}}
   \text{ when } v_\ell|\vartheta_\ell \sim m_{N_{\ell-1},\vartheta_\ell}$$

\If{$\ell \in K\mathbb{N}^*$}
        \State Estimate current standard deviation of the additive noise $\widehat{\sigma}_\ell$ using \eqref{hatsigma}
        \If{$\widehat{\sigma}_\ell > \sigma_{\text{opt}} + \sigma_\text{e}$} \State $N_\ell=N_{\ell}+a$ with probability $p_j$ ($\ell=Kj$)
        \ElsIf{$\widehat{\sigma}_\ell < \sigma_{\text{opt}} - \sigma_\text{e}$ and $N_{\ell-1} > a$}
            \State $N_\ell=N_{\ell}-a$  with probability $p_j$
        \EndIf
        \State Update sample mean $\hat{\theta}_\ell$ of parameters using Equation \eqref{samplemean}

With this function and along with Assumption~\ref{hyp1}, we apply Theorem~\ref{appendix:thm3} and we conclude that there exist constants $\bar{w} \in [1, \infty)$, $M \in [1, \infty)$, $c \geqslant 1$, $\underline{w} \in (0,1]$, and $\delta>0$ such that the polynomial drift condition holds simultaneously for $N \geqslant N_0$:
\begin{align}
    P_N V(\theta, w) \leqslant V(\theta, w) - \delta V^{\frac{\beta-1}{\beta}}(\theta, w) + c\mathds{1}_\mathcal{C}(\theta, w), \end{align}
where $\mathcal{C} =\{(\theta, w) : |\theta|\leqslant M, w\in [\underline{w}, \bar{w}]\}$.

Along with Lemma~\ref{appendix:lemma1} we conclude that there exist $\epsilon_B > 0$ and a probability measure $\nu_B$ such that for all $N \geqslant N_0$ and for all $B$ level sets of $V$,
\begin{align}
P_N(\theta, w; \cdot) \geqslant \epsilon_B \mathds{1}_B(\theta, w) \nu_B(\cdot). \end{align}

We have established $\phi$-irreducibility and aperiodicity, together with the existence of polynomial drift and minorization conditions, simultaneously in $N$, over all level sets of the function $V$. Consequently, all assumptions of Corollary~\ref{appendix:Corollary1} are satisfied. Therefore, there exists a level set \( B \subset \Theta \times \mathcal{W} \) of $V$, constants \( \varepsilon_B, c_B > 0 \), and a probability measure \( \nu_B \) such that
\begin{align*}
P_N(\theta,w ;\cdot) &\geqslant \mathds{1}_B(\theta,w)\, \varepsilon_B \nu_B(\cdot), \quad
P_N V(\theta,w) \leqslant V(\theta,w) - c_B V^{1-\alpha}(\theta,w) + b\, \mathds{1}_B(\theta,w),
\end{align*}
with $\sup_B V < \infty$, $\nu_B(B) > 0$, and $c_B \inf_{B^c} V^{1-\alpha} \geqslant b$.

By Proposition~\ref{appendix:proposition1}, there exists a constant $C$ depending on $\sup_B V$, $\nu(B)$, and $\varepsilon, \alpha, b, c$, such that for any $0 \leqslant \beta \leqslant 1 - \alpha$ and $1 \leqslant \kappa \leqslant \alpha^{-1}(1 - \beta)$,
\begin{equation*}
(n+1)^{\kappa-1}\,\|P_N^n(\theta,w ; \cdot) - \bar\pi_N(\cdot)\|_{V^\beta} \leqslant C\,V^{\beta+\alpha\kappa}(\theta,w).
\end{equation*}

Choosing $\beta=0$ and $\alpha=1/\kappa$, and taking the supremum over $N \geqslant N_0$ and then over $(\theta,w)$, we obtain
\begin{equation}
\lim_{\ell \to \infty} \,
\sup_{(\theta,w) \in \Theta \times \mathcal{W}}
V^{-1}(\theta,w)
\sup_{N \in \mathbb{N}}
\| P^\ell_N((\theta,w), \cdot) - \bar\pi_N \|  = 0, \end{equation}
which is a generalized version of Condition~\eqref{appendix:ii} in Theorem~\ref{appendix:thm4}.

This hierarchical model yields the following observed likelihood:
\begin{align*}
    p(y |\theta)
    &= \prod_{t=1}^{T} \varphi\left(y_t ; \theta, \tfrac{\theta^2 + 2}{\theta^2 + 1}\right).
\end{align*}

